$(errorCatched(() => {

  // [SAVE-SPINNER-20260829] 保存中悬浮窗 v2：只认记录写盘信号，不做降级
  // 信号源：script.js trackChatRecordSave() 广播的 'tt-record-save' 事件（pending = 聊天记录写盘任务数）
  // 三态显示：
  //   橙点        = 未收到信号（script.js 未更新）→ 此指示器不可信，不许作为杀后台依据
  //   淡蓝点      = 已连接且队列空 → 可以杀后台（注意：生成中/编辑后1秒内除外，见使用规则）
  //   转圈+计时   = 队列有任务（含压缩、HTTP 写盘、IndexedDB post-save 全程）
  const ID = 'tt-save-spinner-v1';
  const POS_KEY = 'tt-save-spinner-pos';

  let pdoc, pwin;
  try {
    pdoc = (parent && parent.document) ? parent.document : document;
    pwin = (parent && parent.window) ? parent.window : window;
  } catch (e) {
    pdoc = document;
    pwin = window;
  }

  // 重复导入/启用时清理旧实例（含 v1 fetch 补丁版残留）
  try { pdoc.getElementById(ID)?.remove(); } catch (_) {}
  try { pdoc.getElementById(`${ID}-css`)?.remove(); } catch (_) {}
  try { if (pwin.__ttSaveSpinner?.unpatch) pwin.__ttSaveSpinner.unpatch(); } catch (_) {}
  try { if (pwin.__ttSaveSpinner2?.uninstall) pwin.__ttSaveSpinner2.uninstall(); } catch (_) {}

  // ---- 样式 ----
  const css = pdoc.createElement('style');
  css.id = `${ID}-css`;
  css.textContent = `
    #${ID} { position: fixed !important; z-index: 2147483640 !important; top: 16px; right: 16px; display: flex; align-items: center; gap: 6px; user-select: none; -webkit-user-select: none; touch-action: none; font-family: 'Microsoft YaHei', 'PingFang SC', sans-serif; }
    #${ID} .ball { width: 14px; height: 14px; border-radius: 50%; background: rgba(120,180,235,0.35); box-shadow: 0 1px 6px rgba(100,160,220,0.2); cursor: grab; transition: background 0.2s, box-shadow 0.2s; -webkit-tap-highlight-color: transparent; }
    #${ID} .ball:active { cursor: grabbing; }
    #${ID}.bad .ball { background: rgba(235,160,90,0.55); box-shadow: 0 0 8px rgba(235,160,90,0.5); }
    #${ID}.busy .ball { width: 18px; height: 18px; background: transparent; border: 3px solid rgba(120,180,235,0.25); border-top-color: #4a9fe8; animation: ${ID}-spin 0.9s linear infinite; box-shadow: 0 2px 10px rgba(100,160,220,0.35); }
    @keyframes ${ID}-spin { to { transform: rotate(360deg); } }
    #${ID} .txt { display: none; font-size: 12px; line-height: 1.4; color: #4a8cc2; background: rgba(240,249,255,0.92); border: 1px solid #c8ddf0; border-radius: 8px; padding: 2px 8px; box-shadow: 0 2px 10px rgba(100,160,220,0.18); white-space: nowrap; cursor: grab; }
    #${ID}.busy .txt { display: block; }
    #${ID}.bad-note .txt { display: block; color: #c07a2a; background: rgba(255,248,240,0.95); border-color: #ecd5b8; }
  `;
  pdoc.head.appendChild(css);

  // ---- DOM ----
  const root = pdoc.createElement('div');
  root.id = ID;
  root.innerHTML = `<div class="ball"></div><div class="txt"></div>`;
  (pdoc.documentElement || pdoc.body).appendChild(root);

  const txt = root.querySelector('.txt');

  // ---- 状态 ----
  let connected = false;   // 是否收到过至少一次 tt-save-busy
  let pending = 0;         // 保存队列任务数（事件提供）
  let busySince = 0;       // 本次忙开始时刻
  let tickId = null;
  let noteTimer = null;

  function render() {
    if (pending > 0) {
      root.classList.add('busy');
      root.classList.remove('bad', 'bad-note');
      const sec = Math.max(0, Math.floor((Date.now() - busySince) / 1000));
      const mm = String(Math.floor(sec / 60)).padStart(2, '0');
      const ss = String(sec % 60).padStart(2, '0');
      txt.textContent = `保存中 ${mm}:${ss}` + (pending > 1 ? ` ·队列${pending}` : '');
      if (!tickId) tickId = setInterval(render, 1000);
      return;
    }
    root.classList.remove('busy');
    if (tickId) { clearInterval(tickId); tickId = null; }
    root.classList.toggle('bad', !connected);
  }

  function onBusyEvent(e) {
    connected = true;
    try {
      const d = e?.detail;
      const n = (typeof d === 'number') ? d : (typeof d?.pending === 'number' ? d.pending : 0);
      if (n > 0 && pending === 0) busySince = Date.now();
      if (n === 0) busySince = 0;
      pending = Math.max(0, n);
    } catch (_) {
      pending = 0;
      busySince = 0;
    }
    render();
  }

  // ---- script.js 未更新时的提示（一次性冒泡，橙点常驻）----
  noteTimer = setTimeout(() => {
    if (connected) return;
    txt.textContent = '未接信号：需更新 script.js';
    root.classList.add('bad-note');
    setTimeout(() => { root.classList.remove('bad-note'); }, 6000);
  }, 2500);

  // ---- 安装事件监听 ----
  pwin.addEventListener('tt-record-save', onBusyEvent);

  function uninstall() {
    try { pwin.removeEventListener('tt-record-save', onBusyEvent); } catch (_) {}
    try { if (tickId) clearInterval(tickId); } catch (_) {}
    try { if (noteTimer) clearTimeout(noteTimer); } catch (_) {}
    resetDrag();
    try { pdoc.removeEventListener('pointermove', onDragMove); } catch (_) {}
    try { pdoc.removeEventListener('pointerup', onDragEnd); } catch (_) {}
    try { pdoc.removeEventListener('pointercancel', resetDrag); } catch (_) {}
    try { pwin.removeEventListener('blur', resetDrag); } catch (_) {}
    try { root.remove(); } catch (_) {}
    try { css.remove(); } catch (_) {}
    try { delete pwin.__ttSaveSpinner2; } catch (_) { pwin.__ttSaveSpinner2 = undefined; }
  }
  pwin.__ttSaveSpinner2 = { uninstall };

  // ---- 拖动 + 位置记忆 ----
  let dragging = false, moved = false, sx = 0, sy = 0, rx = 0, ry = 0, watchdog = null;
  function resetDrag() {
    dragging = false;
    moved = false;
    if (watchdog) { clearTimeout(watchdog); watchdog = null; }
  }
  function onDragStart(e) {
    dragging = true;
    moved = false;
    sx = e.clientX;
    sy = e.clientY;
    const rect = root.getBoundingClientRect();
    rx = rect.left;
    ry = rect.top;
    if (watchdog) clearTimeout(watchdog);
    watchdog = setTimeout(resetDrag, 2000);
  }
  function onDragMove(e) {
    if (!dragging) return;
    if (watchdog) { clearTimeout(watchdog); watchdog = setTimeout(resetDrag, 2000); }
    if (!moved && Math.abs(e.clientX - sx) < 4 && Math.abs(e.clientY - sy) < 4) return;
    moved = true;
    root.style.right = 'auto';
    root.style.left = Math.max(0, Math.min(rx + e.clientX - sx, pwin.innerWidth - 40)) + 'px';
    root.style.top = Math.max(0, Math.min(ry + e.clientY - sy, pwin.innerHeight - 40)) + 'px';
  }
  function onDragEnd() {
    if (!dragging) return;
    const wasMoved = moved;
    resetDrag();
    if (wasMoved) {
      const rect = root.getBoundingClientRect();
      try { pwin.localStorage.setItem(POS_KEY, JSON.stringify({ x: Math.round(rect.left), y: Math.round(rect.top) })); } catch (_) {}
    }
  }
  root.addEventListener('pointerdown', onDragStart);
  pdoc.addEventListener('pointermove', onDragMove);
  pdoc.addEventListener('pointerup', onDragEnd);
  pdoc.addEventListener('pointercancel', resetDrag);
  pwin.addEventListener('blur', resetDrag);

  try {
    const saved = JSON.parse(pwin.localStorage.getItem(POS_KEY) || 'null');
    if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) {
      root.style.right = 'auto';
      root.style.left = `${saved.x}px`;
      root.style.top = `${saved.y}px`;
    }
  } catch (_) {}

  // ---- 脚本停用/页面卸载时还原 ----
  window.addEventListener('pagehide', () => { try { uninstall(); } catch (_) {} });
  window.addEventListener('unload', () => { try { uninstall(); } catch (_) {} });

}));
